module TopModule (
    input        in,
    input  [1:0] state,
    output reg [1:0] next_state,
    output reg   out
);

    always @(*) begin
        case (state)
            2'b00: begin // A
                next_state = in ? 2'b01 : 2'b00;
                out = 1'b0;
            end
            2'b01: begin // B
                next_state = in ? 2'b01 : 2'b10;
                out = 1'b0;
            end
            2'b10: begin // C
                next_state = in ? 2'b11 : 2'b00;
                out = 1'b0;
            end
            2'b11: begin // D
                next_state = in ? 2'b01 : 2'b10;
                out = 1'b1;
            end
            default: begin
                next_state = state;
                out = 1'b0;
            end
        endcase
    end

endmodule
